from pandas.api.types import is_numeric_dtype, is_bool_dtype
from collections.abc import Iterable


class PSNode:

    def __init__(self, pos, ntype, before=None, levels=[], info={}):

        self.dx = 10
        self.dy = -4

        self.pos = pos
        self.ntype = ntype
        self.before = before
        self.after = []
        self.nbranch = 0
        self.offset = None

        self.levels = levels

        self.info = info

    def get_root(self):

        node = self.before
        if node is None:
            return self
        else:
            return node.get_root()

    def get_all(self):

        output = [self]
        for node in self.after:
            output.extend(node.get_all())

        return output

    def get_all_lines(self):

        x = []
        y = []
        for node in self.after:
            x1, x2 = self.pos[0], node.pos[0]
            y1, y2 = self.pos[1], node.pos[1]
            if x1 == x2:
                x.extend([np.nan, x1, x2, np.nan])
                y.extend([np.nan, y1, y2, np.nan])
            else:
                xmid = x1 + (x2 - x1)*np.concatenate([np.linspace(0, 0.6, 60), np.linspace(0.61, 1, 5)])
                x.extend([np.nan] + list(xmid) + [np.nan])
                ymid = y2 + (y1 - y2)/(1 + np.exp(4*(xmid - (0.6*x1 + 0.4*x2))))
                y.extend([np.nan] + list(ymid) + [np.nan])
            data = node.get_all_lines()
            x.extend(data[0])
            y.extend(data[1])

        return x, y

    def content_label(self):

        if self.ntype == 'data':
            name, data = self.content
            return f'<b>{name}</b>:<br>{data.shape[0]} x {data.shape[1]}'
        elif self.ntype == 'visual':
            name, _, vtype = self.content
            return f'{vtype} for <b>{name}</b>'
        elif self.ntype == 'model':
            return self.content[2]
        else:
            return 'Unknown'

    def grow(self, ntype, info):

        x = self.pos[0] + self.dx
        y0 = self.pos[1]
        levels = self.levels + [self.nbranch]
        root = self.get_root()
        all_nodes = root.get_all()
        nlevels = len(self.levels)
        upper = []
        lower = []
        lower_nodes = []
        for node in all_nodes:
            if nlevels + 1 == len(node.levels) and nlevels > 0:
                shift = np.array(self.levels) - np.array(node.levels[:nlevels])
                nonzero_indices = np.nonzero(shift)[0]
                if len(nonzero_indices) > 0:
                    if shift[nonzero_indices[0]] > 0:
                        upper.append(node.pos[1])
                    else:
                        lower_nodes.append(node)
                        lower.append(node.pos[1])
        if upper:
            y0 = min(upper) + self.dy if y0 >= min(upper) else y0
        y = y0 + self.dy*self.nbranch
        if lower:
            ymax = max(lower)
            if y <= ymax:
                offset = y - ymax + self.dy
                for node in lower_nodes:
                    node.pos = (node.pos[0], node.pos[1] + offset)

        #next_node = PSNode((x, y), ntype, self, levels, content, code=code)
        next_node = PSNode((x, y), ntype, self, levels, info=info)
        self.after.append(next_node)
        self.nbranch += 1

        return next_node


def to_choices(columns):

    if isinstance(columns, pd.MultiIndex):
        return [', '.join(col) for col in columns.tolist()]
    else:
        return columns.tolist()


def from_tuples(columns):

    if isinstance(columns, (list, pd.MultiIndex)):
        return [', '.join(col) if isinstance(col, tuple) else col 
                for col in columns.tolist()]
    elif isinstance(columns, tuple):
        return ', '.join(columns)
    else:
        return columns


def to_tuples(columns):

    if isinstance(columns, list):
        return [tuple(col.split(', ')) for col in columns]
    else:
        if columns == "":
            return columns
        else:
            return tuple(columns.split(', '))


def str_to_values(string, sup=False):

    try:
        values = eval(string.strip())
    except Exception as err:
        if sup:
            values = None
        else:
            values = err

    return values


def num_cat_labels(data):

    is_num = data.apply(is_numeric_dtype, axis=0).values
    is_bool = data.apply(is_bool_dtype, axis=0).values

    nums = to_choices(data.columns[is_num & (~is_bool)])
    cats = to_choices(data.columns[(~is_num) | is_bool])
    nbs = to_choices(data.columns[is_num])

    return nums, cats, nbs


def operation_params(ops_dict, data, name, ui_input):

    op = ui_input.op_options()
    ops_dict['type'] = op
    ops_dict['output'] = ui_input.output_name().strip()
    ops_dict['markdown'] = ui_input.operation_notes()

    if op == 'Select columns':
        columns = list(ui_input.select_columns())
        if columns == to_choices(data.columns):#.tolist():
            columns = None
        elif isinstance(data.columns, pd.MultiIndex):
            columns = to_tuples(columns)
        ops_dict['params'] = dict(columns=columns)
    elif op == 'Filter rows':
        column = ui_input.filter_column()
        if isinstance(data.columns, pd.MultiIndex):
            column = to_tuples(column)
        current = dict(column=column,
                       opr=ui_input.filter_op(),
                       value=ui_input.filter_value().strip())
        if "filters" not in ops_dict["params"]:
            filters = [current]
        else:
            filters = ops_dict["params"]["filters"]
            filters[-1] = current
        ops_dict["params"] = dict(filters=filters, current=current,
                                  reset_index=ui_input.filter_reset())
    elif op == "Sort rows":
        columns = list(ui_input.sort_columns())
        if isinstance(data.columns, pd.MultiIndex):
            columns = to_tuples(columns)
        ops_dict['params'] = dict(columns=columns,
                                  descending=ui_input.sort_descending(),
                                  reset_index=ui_input.sort_reset())
    elif op == "Treat missing values":
        method = ui_input.nan_method()
        value = ui_input.nan_fill_value() if method == "fill" else None
        nan_switch = ui_input.nan_all_columns_switch()
        columns = list(ui_input.nan_columns()) if not nan_switch else []
        if isinstance(data.columns, pd.MultiIndex):
            columns = to_tuples(columns)
        ops_dict["params"] = dict(method=method, value=value, switch=nan_switch, columns=columns)
    elif op == "Aggregation":
        columns = list(ui_input.agg_columns())
        if columns == to_choices(data.columns):#.tolist():
            columns = None
        elif isinstance(data.columns, pd.MultiIndex):
            columns = to_tuples(columns)
        aggs = list(ui_input.agg_methods())
        transpose = ui_input.agg_transpose()
        ops_dict['params'] = dict(columns=columns, aggs=aggs, transpose=transpose)
    elif op == "Group by":
        columns = list(ui_input.group_by_columns())
        views = list(ui_input.group_view_columns())
        if isinstance(data.columns, pd.MultiIndex):
            columns = to_tuples(columns)
            views = to_tuples(views)
        aggs = list(ui_input.group_methods())
        reset_index = ui_input.group_reset_index()
        ops_dict["params"] = dict(columns=columns, views=views, aggs=aggs, reset_index=reset_index)
    elif op == "Pivot table":
        values = list(ui_input.pivot_values())
        index = list(ui_input.pivot_index())
        columns = list(ui_input.pivot_columns())
        if isinstance(data.columns, pd.MultiIndex):
            values = to_tuples(values)
            index = to_tuples(index)
            columns = to_tuples(columns)
        methods = list(ui_input.pivot_methods())
        reset_index = ui_input.pivot_reset()
        ops_dict["params"] = dict(values=values, index=index, columns=columns, 
                                  methods=methods, reset_index=reset_index)
    elif op == "Add columns":
        col_label = ui_input.add_cols_label().strip()
        exp_type = ui_input.add_cols_type()
        columns = ui_input.add_cols_columns()
        if isinstance(data.columns, pd.MultiIndex):
            columns = to_tuples(columns)
            col_label = (col_label,) + ("",) * (len(data.columns[0]) - 1)
        if exp_type == "":
            formula = ""
            switch = None
        else:
            formula = ui_input.add_cols_expression() if exp_type != "To dummies" else ""
        switch = ui_input.add_cols_switch() if exp_type == "To dummies" else None
        binary = ui_input.add_cols_binary() if exp_type == "To dummies" else None
        ops_dict["params"] = dict(label=col_label, type=exp_type, columns=columns,
                                  formula=formula, drop=switch, binary=binary)
    else:
        ops_dict['params'] = {}                                    

    ops_dict['code']  = operation_code(name, ops_dict)


def operation_code(name, op_dict):

    op = op_dict['type']
    output_name = op_dict['output']
    params = op_dict['params']

    left = f"{output_name} = " if output_name != '' else ""
    if op == "Select columns":
        if params["columns"] is not None:
            return (
                f"columns = {params['columns']}\n"
                f"{left}{name}[columns].copy()"
            )
        else:
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}"
    elif op == "Filter rows":
        filters = op_dict["params"]["filters"]
        cond_lines = []
        if len(filters) > 0:
            for i, filter in enumerate(filters):
                values_str = filter["value"]
                if values_str == "":
                    break
                values = str_to_values(values_str)
                if isinstance(values, Exception):
                    op_dict["error"] = values
                    break
                else:
                    op_dict["error"] = None
                if filter["column"] == "" or filter["opr"] == "":
                    break
                if filter["opr"] in ["in", "not in"]:
                    if isinstance(values, Iterable) and not isinstance(values, str):
                        values = list(values)
                    else:
                        values = [values]
                    not_code = "~" if filter["opr"] == "not in" else ""
                    opr_code = f".isin({values.__repr__()})"
                else:
                    not_code = ""
                    opr_code = f" {filter['opr']} {values.__repr__()}"
                cond_code = f"cond{i+1} = {not_code}{name}[{filter['column'].__repr__()}]{opr_code}"
                cond_lines.append(cond_code)

        if len(cond_lines) > 0:
            rows_code = " & ".join([f"cond{i}"for i in range(1, 1 + len(cond_lines))])
            reset_code = ".reset_index(drop=True)" if params["reset_index"] else ""
            return (
                f"{'\n'.join(cond_lines)}\n"
                f"{left}{name}[{rows_code}]{reset_code}"
            )
        else:
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}"
    elif op == "Sort rows":
        if len(params["columns"]) > 0:
            descending_code = f", ascending=False" if params["descending"] else ""
            columns_code = params["columns"][::-1].__repr__()
            reset_code = ".reset_index(drop=True)" if params["reset_index"] else ""
            return f"{left}{name}.sort_values({columns_code}{descending_code}){reset_code}"
        else:
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}"
    elif op == "Treat missing values":
        method = params["method"]
        switch = params["switch"]
        columns = params["columns"]
        if method == "drop":
            if switch:
                return f"{left}{name}.dropna()"
            else:
                if len(columns) > 0:
                    return (
                        f"missing = {name}[{columns.__repr__()}].isnull().any(axis=1)\n"
                        f"{left}{name}.loc[~missing]"
                    )
        elif method == "fill":
            value_str = params["value"]
            if value_str == "":
                right = "" if left == "" else ".copy()"
                return f"{left}{name}{right}"

            if switch:
                return f"{left}{name}.fill({value_str})"
            else:
                if len(columns) > 0:
                    if left == "":
                        copy_code = f"{name}_copy = {name}.copy()"
                        copy_name = f"{name}_copy"
                    else:
                        copy_code = f"{left}{name}.copy()"
                        copy_name = output_name
                    return (
                        f"{copy_code}\n"
                        f"columns = {columns.__repr__()}\n"
                        f"{copy_name}.loc[:, columns] = {name}.loc[:, columns].fillna({value_str})\n"
                        f"{copy_name}"
                    )

        right = "" if left == "" else ".copy()"
        return f"{left}{name}{right}"

    elif op == "Aggregation":
        aggs = params["aggs"]
        transpose_code = ".transpose()" if params["transpose"] else ""
        if params["columns"] is not None:
            return (
                f"columns = {params['columns']}\n"
                f"{left}{name}[columns].agg({aggs}){transpose_code}"
            )
        else:
            return f"{left}{name}.agg({aggs}{transpose_code})"
    elif op == 'Group by':
        columns = params["columns"]
        views = params["views"]
        aggs = params["aggs"]
        reset_index = params["reset_index"]
        reset_code = ".reset_index()" if reset_index else ""
        if columns != [] and views != [] and aggs != []:
            return (
                f"{left}{name}.groupby({columns.__repr__()})[{views.__repr__()}].agg({aggs.__repr__()}){reset_code}"
            )
        else:
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}"
    elif op == "Pivot table":
        values = params['values']
        index = params['index']
        columns = params['columns']
        methods = params["methods"]
        if values != [] and index != [] and columns != [] and methods != []:
            values_code = f"values = {values.__repr__()}"
            index_code = f"index = {index.__repr__()}"
            columns_code = f"columns = {columns.__repr__()}"
            methods_code = f"func = {methods.__repr__()}"
            reset_code = ".reset_index()" if params["reset_index"] else ""
            return (
                f"{values_code}\n"
                f"{index_code}\n"
                f"{columns_code}\n"
                f"{methods_code}\n"
                f"{left}{name}.pivot_table(values, index, columns, aggfunc=func){reset_code}"
            )
        else:
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}"
    elif op == "Add columns":
        label = params["label"].__repr__()
        exp_type = params["type"]
        columns = params["columns"].__repr__()
        formula = params["formula"]
        df_name = "temp" if left == "" else f"{output_name}"
        copy_code = f"temp = {name}.copy()" if left == "" else f"{left}{name}.copy()"
        output_code = "\ntemp" if left == "" else ""

        if (formula == "" and exp_type != "To dummies") or params["label"] == "":
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}" 

        if exp_type == "Arithmetic expression":
            transform_code = f"{df_name}[{label}] = {formula}"
        elif exp_type == "Type conversion":
            transform_code = f"{df_name}[{label}] = {df_name}[{columns}].astype({formula})"
        elif exp_type == "String operations":
            transform_code = f"{df_name}[{label}] = {df_name}[{columns}].str{formula}"
        elif exp_type == "To date time":
            expr = f"pd.to_datetime({df_name}[{columns}], format={formula.__repr__()})"
            transform_code = f"{df_name}[{label}] = {expr}"
        elif exp_type == "To dummies":
            drop_code = ", drop_first=True" if params["drop"] else ""
            cat_code = '{cat}'
            binary_code = ".astype(int)" if params["binary"] else ""
            transform_code = (
                f"dummies = pd.get_dummies({df_name}[{columns}]{drop_code}){binary_code}\n"
                f"columns = [f'{params['label']}_{cat_code}' for cat in dummies.columns]\n"
                f"{df_name}[columns] = dummies"
            )
        else:
            right = "" if left == "" else ".copy()"
            return f"{left}{name}{right}"

        return (
            f"{copy_code}\n"
            f"{transform_code}"
            f"{output_code}"
        )

        #columns = params["columns"]

        #drop = params["drop"]

    else:
        return f'{left}{name}.copy()'


def operation_exec(data, name, op_dict):

    try:
        error = op_dict["error"]
        if error is not None:
            raise error
        code = op_dict['code']

        exec(f"{name} = data")
        output_name = op_dict["output"]
        if output_name == "":
            lines = code.split("\n")
            exec("\n".join(lines[:-1]))
            return eval(lines[-1])
        else:
            exec(code)
            #op_dict["output_data"] = eval(output_name)
            return eval(output_name)
    except Exception as err:
        return str(err)


def visual_params(dvs_dict, data, name, ui_input, color, col_dict):

    dv = ui_input.dv_options()
    dvs_dict['type'] = dv
    dvs_dict['markdown'] = ui_input.visual_notes()
    color_value = color.get()

    imports = ['import matplotlib.pyplot as plt']
    if dv == "Univariate analysis":
        method_value = ui_input.uni_type()
        column = ui_input.uni_column()

        if isinstance(data.columns, pd.MultiIndex):
            column = to_tuples(column)
        plot = dict(
            column=column, 
            method=method_value,
            color=color_value,
            #color=ui_input.uni_color(),
            alpha=ui_input.uni_alpha()
        )
        if method_value == 'hist':
            plot['bins'] = ui_input.bins()
        elif method_value in ['boxplot', 'value counts']:
            plot['dir'] = ui_input.uni_dir()
        if method_value in ['hist', 'value counts']:
            plot['ydata'] = ui_input.uni_ydata()
        if method_value == "kde":
            imports.append("import seaborn as sns")
    elif dv == "Bar chart":
        xdata = ui_input.bar_xdata()
        ydata = ui_input.bar_ydata()
        if isinstance(data.columns, pd.MultiIndex):
            xdata = to_tuples(xdata)
            ydata = to_tuples(ydata)
        current=dict(ydata=ydata, color=color_value)

        if "bars" not in dvs_dict["plot"]:
            bars = [current]
        else:
            bars = dvs_dict["plot"]["bars"].copy()
            bars[-1] = current
        plot = dict(
            xdata=xdata,
            dir=ui_input.bar_dir(),
            mode=ui_input.bar_mode(),
            width=ui_input.bar_width(),
            color="",
            alpha=ui_input.bar_alpha(),
            bars=bars,
            current=current
        )
    elif dv == "Scatter plot":
        xdata = ui_input.scatter_xdata()
        ydata = ui_input.scatter_ydata()
        if isinstance(data.columns, pd.MultiIndex):
            xdata = to_tuples(xdata)
            ydata = to_tuples(ydata)
        plot = dict(
            xdata=xdata,
            ydata=ydata,
            scale=ui_input.scatter_scale(),
            color=color_value,
            alpha=ui_input.scatter_alpha()
        )
        plot["color_switch"] = ui_input.scatter_color_switch()
        color_col = ui_input.scatter_color_col() if plot["color_switch"] else ""
        if isinstance(data.columns, pd.MultiIndex):
            color_col = to_tuples(color_col)
        plot["color_col"] = color_col
        plot["cmap"] = ui_input.scatter_cmap() if plot["color_switch"] else ""
        plot["size_switch"] = ui_input.scatter_size_switch()
        size_col = ui_input.scatter_size_col() if plot["size_switch"] else ""
        if isinstance(data.columns, pd.MultiIndex):
            size_col = to_tuples(size_col)
        plot["size_col"] = size_col
    elif dv == "Line plot":
        xdata = ui_input.line_xdata()
        ydata = ui_input.line_ydata()
        if isinstance(data.columns, pd.MultiIndex):
            xdata = to_tuples(xdata)
            ydata = to_tuples(ydata)
        current=dict(xdata=xdata,
                     ydata=ydata,
                     color=color_value,
                     transform=ui_input.line_trans(),
                     step=ui_input.line_step(),
                     style=ui_input.line_style(),
                     marker=ui_input.line_marker(),
                     scale=ui_input.line_marker_scale(),
                     width=ui_input.line_width())
        if "lines" not in dvs_dict["plot"]:
            lines = [current]
        else:
            lines = dvs_dict["plot"]["lines"].copy()
            lines[-1] = current
        plot = dict(
            color="",
            alpha=1,
            lines=lines,
            current=current
        )
    else:
        plot = dict(color="#1f77b4", alpha=1)
        #imports = []

    if dv != "":
        fig = dict(title=ui_input.fig_title(), fontsize=ui_input.fig_fontsize(),
               xlabel=ui_input.fig_xlabel(), ylabel=ui_input.fig_ylabel(),
               legend_loc=ui_input.fig_legend_loc(), xtick_rotate=ui_input.fig_xtick_rotate(),
               grid=ui_input.fig_grid(), 
               width=ui_input.fig_width(), height=ui_input.fig_height())
    else:
        fig = dict(title="", fontsize=10, xlabel="", ylabel="", legend_loc="upper left",
                   xtick_rotate=0, grid=False, width=640, height=480)

    dvs_dict['plot'] = plot
    dvs_dict['fig'] = fig
    dvs_dict['imports'] = imports
    dvs_dict['code'] = visual_code(name, dvs_dict, col_dict)


def visual_code(name, dvs_dict, col_dict):

    dv = dvs_dict['type']
    plot = dvs_dict['plot']
    fig = dvs_dict['fig']
    # imports = dvs_dict['imports']

    color = plot["color"]
    color_code = "" if color == "#1f77b4" else f", color={color.__repr__()}"
    alpha = plot["alpha"]
    alpha_code = "" if alpha == 1 else f", alpha={alpha}"

    font = fig['fontsize']
    legend_loc = fig["legend_loc"]
    font_code = "" if int(font) == 10 else f", fontsize={font}"

    if dv == 'Univariate analysis':
        column = plot["column"]
        if column == "":
            plot_code = ""
        elif plot["method"] == "hist":
            bins = plot['bins']
            bins_code = "" if bins == 10 else f", bins={bins}"
            ydata_code = "" if plot['ydata'] == 'Count' else ", density=True"
            plot_code = (
                f"plt.hist({name}"
                f"[{column.__repr__()}]{bins_code}{ydata_code}{color_code}{alpha_code})\n"
            )
        elif plot["method"] == "kde":
            plot_code = (
                f"col = {name}[{column.__repr__()}]\n"
                f"sns.kdeplot(col, fill=True{color_code}{alpha_code})\n"
            )
        elif plot["method"] == "boxplot":
            vert_value = "True" if plot["dir"] == "Vertical" else "False"
            plot_code = (
                f"col = {name}[{column.__repr__()}]\n"
                f"plt.boxplot(col, labels=[''], vert={vert_value}, patch_artist=True,\n"
                f"            boxprops=dict(facecolor={color.__repr__()}{alpha_code}))\n"
            )
        elif plot["method"] == "value counts":
            ydata_code = "" if plot["ydata"] == "Count" else "normalize=True"
            if plot["dir"] == "Vertical":
                bar_code = "bar" 
                sort_code = ""
            else:
                bar_code = "barh"
                sort_code = ".sort_values(ascending=True)"
            plot_code = (
                f"counts = {name}[{column.__repr__()}].value_counts({ydata_code}){sort_code}\n"
                f"plt.{bar_code}(counts.index, counts.values{color_code}{alpha_code})\n"
            )
        else:
            plot_code = ""
    elif dv == "Bar chart":
        ydata_cols = []
        ydata_colors = []
        for bar in dvs_dict["plot"]["bars"]:
            if bar["ydata"] == "":
                break
            ydata_cols.append(bar["ydata"])
            ydata_colors.append(bar["color"])

        if len(ydata_cols) > 0:
            xdata_col = plot["xdata"]
            xdata_code = "" if xdata_col == "" else f"x={xdata_col.__repr__()}, "

            width = plot["width"]
            bar_func = "bar" if plot["dir"] == 'Vertical' else "barh"
            stacked_code = "" if plot["mode"] == "clustered" else ", stacked=True"
            legend_code = "" if len(ydata_cols) <= 1 else f"plt.legend(loc={legend_loc.__repr__()}{font_code})\n"

            shift = " " *(len(name) + (bar_func == "barh"))
            plot_code = (
                f"{name}.plot.{bar_func}({xdata_code}y={ydata_cols.__repr__()},\n"
                f"{shift}          color={ydata_colors.__repr__()}{alpha_code}, width={width}{stacked_code},\n"
                f"{shift}          xlabel='', ylabel='', legend=False, ax=fig.gca())\n"
                f"{legend_code}"
            )
        else:
            plot_code = ""
    elif dv == "Scatter plot":
        xdata, ydata = plot["xdata"], plot["ydata"]
        if xdata != "" and ydata != "":
            xdata_code = f"{name}[{xdata.__repr__()}]"
            ydata_code = f"{name}[{ydata.__repr__()}]"
            scale = plot["scale"]
            multiplier = 25**(scale-1)
            if plot["size_col"] != "":
                multi_code = "" if multiplier == 1 else f"*{multiplier:.3f}"
                size_code = f", s={name}[{plot["size_col"].__repr__()}]{multi_code}"
            else:
                size_code = "" if scale == 1 else f", s={36*multiplier:.3f}"

            color_col = plot["color_col"]
            if plot["color_switch"] and color_col != "":
                color_code = f", c={name}[{plot["color_col"].__repr__()}]"
                cbar_code = "plt.colorbar()\n"
                cmap_code = f"plt.set_cmap({plot['cmap'].__repr__()})\n"
            else:
                cbar_code = ""
                cmap_code = ""

            if from_tuples(color_col) in col_dict["nbs"] or color_col == "":
                plot_code = (
                    f"plt.scatter({xdata_code}, {ydata_code}{size_code}{color_code}{alpha_code})\n"
                    f"{cmap_code}"
                    f"{cbar_code}"
                )
            else:
                col_code = f"{name}[{color_col.__repr__()}]"
                xdata_code = f"{name}_each[{xdata.__repr__()}]"
                ydata_code = f"{name}_each[{ydata.__repr__()}]"
                size_code = size_code.replace(f"s={name}", f"s={name}_each")
                if plot["cmap"] == "tab10":
                    cmap_code = ""
                    color_code = ""
                else:
                    cmap_code = (
                        f"colors = plt.cm.{plot["cmap"]}.colors\n"
                        "num_colors = len(colors)\n"
                    )
                    color_code = ", c=colors[i%num_colors]"
                plot_code = (
                    f"{cmap_code}"
                    f"for i, cat in enumerate({col_code}.unique()):\n"
                    f"    {name}_each = {name}.loc[{col_code} == cat]\n"
                    f"    plt.scatter({xdata_code}, {ydata_code}{size_code}{color_code}{alpha_code}, label=cat)\n"
                    f"plt.legend(loc={legend_loc.__repr__()}{font_code})\n"
                )
        else:
            plot_code = ""
    elif dv == "Line plot":
        line_code = []
        markers = {"none": "",
                   "circle": "o", "square": "s", "diamond": "d", "triangle": "^",
                   "dot": ".", "star": "*", "cross": "x"}
        styles = {"solid": "-", "dash": "--", "dot": ":", "dash-dot": "-."}
        for line in dvs_dict["plot"]["lines"]:
            if line["ydata"] == "":
                break
            xdata_code = "" if line["xdata"] == "" else f"{name}[{line['xdata'].__repr__()}], "
            step = line["step"]
            trans_funs = {"none": "",
                          "change": f".diff({step})",
                          "pct change": f".pct_change({step})",
                          "moving average": f".rolling({step}).mean()"}
            trans_label = {"none": "",
                           "change": f"{step}-step change of ",
                           "pct change": f"{step}-step fractional change of ",
                           "moving average": f"{step}-step moving average of "}
            ydata_code = f"{name}[{line['ydata'].__repr__()}]{trans_funs[line['transform']]}"
            color_code = f", color={line["color"].__repr__()}"
            width_code = f"linewidth={line['width']}"
            style = styles[line["style"]]
            style_code = "" if style == '-' else f", linestyle={style.__repr__()}"
            marker = markers[line["marker"]]
            marker_code = "" if marker == '' else f", marker={marker.__repr__()}"
            scale = 3**(line["scale"] - 1)
            scale_code = "" if scale == 1 else f", markersize={6*scale:.3f}"
            label_str = f"{trans_label[line['transform']]}{line['ydata']}"
            each_code = (
                f"plt.plot({xdata_code}{ydata_code}{color_code},\n"
                f"         {width_code}{style_code}{marker_code}{scale_code}, label={label_str.__repr__()})"
            )
            line_code.append(each_code)

        legend_code = "" if len(line_code) < 2 else f"plt.legend(loc={legend_loc.__repr__()}{font_code})\n"
        plot_code = (
            f"{'\n'.join(line_code)}\n"
            f"{legend_code}"
        )

    else:
        plot_code = ""

    xlabel = fig['xlabel']
    xlabel_code = "" if xlabel == '' else f"plt.xlabel({xlabel.__repr__()}{font_code})\n"
    ylabel = fig['ylabel']
    ylabel_code = "" if ylabel == '' else f"plt.ylabel({ylabel.__repr__()}{font_code})\n"

    width, height = fig["width"]/100, fig["height"]/100
    figsize_code = f"figsize=({width}, {height})"
    fig_code = f"fig = plt.figure({figsize_code})\n"

    title = fig["title"]
    title_code = "" if title == "" else f"plt.title({title.__repr__()}{font_code})\n"

    rotate = fig["xtick_rotate"]
    align = "center" if rotate%90== 0 else "left" if rotate < 0 else "right"

    rotate_cond = (rotate == 0) and (dv != "Bar chart") #and plot_code != ""
    rotate_code = "" if rotate_cond else f"plt.xticks(rotation={rotate}, ha={align.__repr__()})\n"

    grid_code = "plt.grid()\n" if fig["grid"] is True else "" 

    return (
        f"{fig_code}"
        f"{title_code}"
        f"{plot_code}"
        f"{xlabel_code}{ylabel_code}"
        f"{rotate_code}"
        f"{grid_code}"
        "plt.show()"
    )


def visual_exec(data, name, dvs_dict):

    try:
        code = dvs_dict["code"]
        code_lines = code.split("\n")
        exec(f"{name} = data")

        width = dvs_dict["fig"]['width'] / 100
        height = dvs_dict["fig"]['height'] / 100
        fig = plt.figure(figsize=(width, height))
        exec("\n".join(code_lines[1:-1]))

        return fig

    except Exception as err:
        return str(err)


def export(nodes):

    import_map = {'sns': 'import seaborn as sns',
                  'plt': 'import matplotlib.pyplot as plt',
                  'smf': 'import statsmodels.formula.api as smf',
                  'pd': 'import pandas as pd',
                  'np': 'import numpy as np'}

    from_map = {'Pipeline': 'from sklearn.pipeline import Pipeline',
                'OneHotEncoder': 'from sklearn.preprocessing import OneHotEncoder',
                'StandardScaler': 'from sklearn.preprocessing import StandardScaler',
                'Normalizer': 'from sklearn.preprocessing import Normalizer',
                'PCA': 'from sklearn.decomposition import PCA',
                'DecisionTreeRegressor': 'from sklearn.tree import DecisionTreeRegressor',
                'DecisionTreeClassifier': 'from sklearn.tree import DecisionTreeClassifier',
                'RandomForestRegressor': 'from sklearn.ensemble import RandomForestRegressor',
                'RandomForestClassifier': 'from sklearn.ensemble import RandomForestClassifier',
                'ColumnTransformer': 'from sklearn.compose import ColumnTransformer',
                'LinearRegression': 'from sklearn.linear_model import LinearRegression',
                'Lasso': 'from sklearn.linear_model import Lasso',
                'Ridge': 'from sklearn.linear_model import Ridge',
                'LogisticRegression': 'from sklearn.linear_model import LogisticRegression',
                'KFold': 'from sklearn.model_selection import KFold',
                'train_test_split': 'from sklearn.model_selection import train_test_split',
                'cross_val_score': 'from sklearn.model_selection import cross_val_score',
                'cross_val_predict': 'from sklearn.model_selection import cross_val_predict',
                'roc_curve': 'from sklearn.metrics import roc_curve, confusion_matrix',
                'GridSearchCV': 'from sklearn.model_selection import GridSearchCV'}

    code_cells = []
    all_imports = set()
    for node in nodes:
        info = node.info
        key = "ops" if node.ntype == "data" else "dvs"
        code = info[key]["code"]
        markdown = info[key]["markdown"]
        import_str = '\n'.join(info[key]["imports"])
        for alias in import_map:
            if f'as {alias}' in import_str:
                all_imports.add(alias)

        for name in from_map:
            if f'import {key}' in import_str:
                all_imports.add(name)

        if markdown.strip() != "":
            markdown_dict = dict(cell_type="markdown", metadata={}, source=f"{markdown}")
            code_cells.append(markdown_dict)

        code_dict = dict(cell_type='code', metadata={}, source=f'{code}')
        code_cells.append(code_dict)

    imports = ['import pandas as pd',
               'import numpy as np']
    for item in all_imports:
        if item in import_map and item not in ['pd', 'np']:
            imports.insert(2, import_map[item])
        if item in from_map:
            imports.append(from_map[item])
    import_cell = dict(cell_type='code', metadata={}, source='\n'.join(imports))
    code_cells.insert(0, import_cell)

    return {
        "metadata" : {
            "signature": "hex-digest",
            "kernel_info": {
                "name" : "the name of the kernel"
            },
        },
        "nbformat": 4,
        "nbformat_minor": 0,
        "cells" : code_cells,
    }


