                    ydata = input.bar_ydata()
                    if isinstance(data.columns, pd.MultiIndex):
                        ydata = to_tuples(ydata)            
                    plot["bars"].append(dict(ydata=ydata, color=color.get()))

                    ui.update_selectize("bar_ydata", selected="")

                @reactive.effect
                @reactive.event(input.add_line)
                def add_line_button():

                    node = node_input.get()
                    data = node["data"]

                    plot = dvs.get()["plot"]
                    ydata = input.line_ydata()
                    xdata = input.line_xdata()
                    if isinstance(data.columns, pd.MultiIndex):
                        ydata = to_tuples(ydata)     
                        xdata = to_tuples(xdata)       

                    current = dict(xdata=xdata, ydata=ydata,
                                   color=color.get(),
                                   transform=input.line_trans(),
                                   step=input.line_step(),
                                   style=input.line_style(),
                                   marker=input.line_marker(),
                                   scale=input.line_marker_scale(),
                                   width=input.line_width())
