                            data = node["data"]
                            if data is None:
                                return
                            name = node["name"]
                            dvs_dict = dvs.get()
                            col_nums, col_cats, col_nbs = num_cat_labels(data)
                            col_dict = dict(nums=col_nums, cats=col_cats, nbs=col_nbs)

                            visual_params(dvs_dict, data, name, input, color, col_dict)
                            fig = visual_exec(data, name, dvs_dict)
                            if isinstance(fig, str):
                                ui_block(fig, "danger")
                            else:
                                width = input.fig_width()
                                height = input.fig_height()
                                @render.plot(width=width, height=height)
                                def visual_figure_preview(): 
                                    return fig

                                _ = dvs_view.set(dict(fig=fig, width=width, height=height))


