                ui.input_action_button("save_visual", "Save")


            @reactive.effect
            @reactive.event(input.cancel_visual)
            def cancel_visual_node():

                ui.update_text_area("visual_notes", value="")
                ui.update_selectize("dv_options", selected="")
                color.set("#1f77b4")

            @reactive.effect
            @reactive.event(input.save_visual)
            def save_visual_node():

                dvs_dict = dvs.get()
                node_list = nodes.get()
                cs = node_highlights.get()
                root = node_list[cs.index("red")]
                info = dict(view=dvs_view.get().copy(), dvs=dvs_dict.copy())
                node_view.set(info["view"])
                node_list.append(root.grow("visual", info=info))

                cs = ["gray"] * len(cs) + ["red"]
                node_highlights.set(cs)
                arc_highlights.set(["gray"] * len(cs))
                node_input.set(dict(name="", data=None))

                ui.update_action_button("to_ops", disabled=True)
                ui.update_action_button("to_dvs", disabled=True)
                ui.update_action_button("to_mds", disabled=True)

                ui.update_text_area("visual_notes", value="")
                ui.update_selectize("dv_options", selected="")
                color.set("#1f77b4")

